function categorize(feedback) {
  const t = feedback.toLowerCase();
  if (t.includes("love") || t.includes("great")) return "praise";
  if (t.includes("couldn't") || t.includes("can't") || t.includes("confusing")) return "issue";
  return "suggestion";
}
console.log(categorize("I couldn't find the filter"));

